    private static ArrayList<DownloadOption> uniqueOptions(Collection<DownloadOption> rows){LinkedHashMap<String,DownloadOption> map=new LinkedHashMap<>();if(rows!=null)for(DownloadOption option:rows){if(option==null||option.episode==null)continue;String url=safeUrl(option.episode.streams.get(option.quality));if(url.isEmpty())continue;String voice=voiceKey(option.voice+" "+option.episode.name);String urlKey=Integer.toHexString(url.hashCode());String key=episodeParam(option.episode.number)+"|"+option.quality+"|"+(voice.isEmpty()?"unknown:"+urlKey:voice);if(!map.containsKey(key))map.put(key,option);}ArrayList<DownloadOption> out=new ArrayList<>(map.values());out.sort((a,b)->{int va=YoruApp.app().store.voicePriority(a.voice+" "+(a.episode==null?"":a.episode.name)),vb=YoruApp.app().store.voicePriority(b.voice+" "+(b.episode==null?"":b.episode.name));if(va!=vb)return Integer.compare(va<0?999:va,vb<0?999:vb);int sa=SourceEngine.score(a.source==null?"":a.source.source,a.source),sb=SourceEngine.score(b.source==null?"":b.source.source,b.source);int p=sb-sa;if(p!=0)return p;return Integer.compare(b.quality,a.quality);});return out;}
