    private void collectDetailsOptions(ArrayList<DownloadOption> out,Anime base,double number,String voice,int maxQuality,boolean strictVoice){if(!Anime.valid(base))return;try{collectOptions(out,details(base,true),number,voice,maxQuality,strictVoice);}catch(Exception ignored){}}
    private void collectCatalogOptions(ArrayList<DownloadOption> out,Anime base,double number,String voice,int maxQuality,boolean strictVoice){if(!Anime.valid(base))return;ArrayList<Anime> matches=new ArrayList<>();for(String s:SourceEngine.discoveryOrder(base,null)){try{for(Anime candidate:catalog(s,base.original.isEmpty()?base.title:base.original,1,new Filter()).items)if(candidate!=null&&SourceEngine.identity(candidate).equals(SourceEngine.identity(base)))matches.add(candidate);}catch(Exception ignored){}if(matches.size()>=4)break;}matches.sort((a,b)->SourceEngine.score(b.source,b)-SourceEngine.score(a.source,a));for(Anime candidate:matches){collectOptions(out,candidate,number,voice,maxQuality,strictVoice);if(enoughDownloadOptions(out,voice,maxQuality,strictVoice))break;}}
    private void collectIframeOptions(ArrayList<DownloadOption> out,Anime base,double number){try{Anime.Playback ready=playback(base,Sec.s("3f1c11101e"));String url=ready==null?"":embed(ready.directUrl);if(url.isEmpty()&&ready!=null&&ready.video!=null){Anime.Episode ep=findEpisode(ready.video,number);if(ep!=null){loadEpisode(ep);if(!ep.variants.isEmpty())url=embed(ep.variants.get(0).url);}}if(url.isEmpty())return;TreeMap<Integer,String> streams=resolveStreams(url);for(Map.Entry<Integer,String> stream:streams.entrySet()){String safe=safeUrl(stream.getValue());if(safe.isEmpty())continue;Anime source=Anime.from(base.json());source.source=Sec.s("3f1c11101e");source.id=base.id.isEmpty()?String.valueOf(Math.abs(base.key().hashCode())):base.id;Anime.Episode ep=new Anime.Episode();ep.id=source.id+"-"+episodeParam(number)+"-"+stream.getKey();ep.number=number;ep.name="";ep.streams.put(stream.getKey(),safe);out.add(new DownloadOption(source,ep,stream.getKey(),"","Tsuyu"));}}catch(Exception ignored){}}
    private static Anime.Episode findEpisode(Anime anime,double number){if(anime==null)return null;Anime.Episode fallback=null;double best=Double.MAX_VALUE;for(Anime.Episode ep:anime.episodeList){if(ep==null||ep.future)continue;if(sameEpisode(ep.number,number))return ep;double diff=Math.abs(ep.number-number);if(diff<best){best=diff;fallback=ep;}}return fallback;}
    public List<DownloadOption> downloadOptions(Anime a,Anime.Playback current,double number)throws Exception{SecureStore store=YoruApp.app().store;return downloadOptions(a,current,number,store.voicePreference(),store.downloadResolution(),store.onlyPreferredVoice());}
    public List<DownloadOption> downloadOptions(Anime a,Anime.Playback current,double number,String voice,int maxQuality,boolean strictVoice)throws Exception{ArrayList<DownloadOption> out=new ArrayList<>();if(current!=null&&current.video!=null)collectOptions(out,current.video,number,voice,maxQuality,strictVoice);if(enoughDownloadOptions(out,voice,maxQuality,strictVoice))return uniqueOptions(out);collectDetailsOptions(out,a,number,voice,maxQuality,strictVoice);if(enoughDownloadOptions(out,voice,maxQuality,strictVoice))return uniqueOptions(out);Anime yoru=yoruShell(a);if(Anime.valid(yoru))collectOptions(out,yoru,number,voice,maxQuality,strictVoice);if(enoughDownloadOptions(out,voice,maxQuality,strictVoice))return uniqueOptions(out);Anime max=null;try{max=findYummy(a);}catch(Exception ignored){}if(Anime.valid(max))collectOptions(out,max,number,voice,maxQuality,strictVoice);if(enoughDownloadOptions(out,voice,maxQuality,strictVoice))return uniqueOptions(out);if(!strictVoice)collectIframeOptions(out,a,number);if(!out.isEmpty())return uniqueOptions(out);if(strictVoice&&!voiceKey(voice).isEmpty()){ArrayList<DownloadOption> fallback=new ArrayList<>();if(current!=null&&current.video!=null)collectOptions(fallback,current.video,number,"",maxQuality,false);collectDetailsOptions(fallback,a,number,"",maxQuality,false);if(Anime.valid(yoru))collectOptions(fallback,yoru,number,"",maxQuality,false);if(Anime.valid(max))collectOptions(fallback,max,number,"",maxQuality,false);if(fallback.isEmpty())collectIframeOptions(fallback,a,number);if(fallback.isEmpty())collectCatalogOptions(fallback,a,number,"",maxQuality,false);return uniqueOptions(fallback);}collectCatalogOptions(out,a,number,voice,maxQuality,false);return uniqueOptions(out);}

    private Anime.Page yoruCatalog(String search,int page,Filter f)throws Exception{String q=search==null?"":search.trim();Anime.Page base;try{base=catalog(Sec.s("271b1c121c3e0a111b"),q,page,f);}catch(Exception first){base=catalog(Sec.s("2d0618140c"),q,page,f);}Anime.Page out=new Anime.Page();out.page=base.page;out.total=base.total;out.more=base.more;out.note="Tsuyu";for(Anime item:base.items)out.items.add(remember(yoruShell(item)));ArrayList<Integer> anilistAt=new ArrayList<>();if(!q.isEmpty()){try{Anime.Page extra=anilistCatalog(q,1);for(Anime item:extra.items){if(out.items.size()>=24)break;boolean dup=false;for(Anime h:out.items){if(item.malId>0&&h.malId==item.malId){dup=true;break;}String hi=SourceEngine.identity(h);if(!hi.isEmpty()&&hi.equals(SourceEngine.identity(item))){dup=true;break;}if(!h.title.isEmpty()&&(h.title.equalsIgnoreCase(item.title)||h.original.equalsIgnoreCase(item.original))){dup=true;break;}}if(!dup){out.items.add(remember(yoruShell(item)));anilistAt.add(out.items.size()-1);}}}catch(Exception ignored){}}if(!anilistAt.isEmpty()&&page==1)canonicalize(out,anilistAt);return out;}
    private void canonicalize(Anime.Page out,ArrayList<Integer> at){ArrayList<Integer> need=new ArrayList<>();for(int idx:at){if(idx<0||idx>=out.items.size())continue;int id=out.items.get(idx).malId;if(id>0&&!need.contains(id))need.add(id);if(need.size()>=12)break;}if(need.isEmpty())return;StringBuilder ids=new StringBuilder();for(int id:need){if(ids.length()>0)ids.append(',');ids.append(id);}JSONArray rows;try{StringBuilder qs=new StringBuilder();qs.append(Sec.s("2f121b101836164b1b01077147")).append(ids).append(Sec.s("765f1910183a1159")).append(need.size()).append(Sec.s("7d08")).append(SH_FIELDS).append(Sec.s("290e"));rows=shiki(qs.toString()).optJSONArray("animes");}catch(Exception ignored){return;}if(rows==null||rows.length()==0)return;Map<Integer,Anime> canon=new HashMap<>();for(int i=0;i<rows.length();i++){JSONObject raw=rows.optJSONObject(i);if(raw==null)continue;Anime e=shikiAnime(raw);if(e!=null&&e.malId>0&&Anime.valid(e))canon.put(e.malId,remember(e));}for(int idx:at){if(idx<0||idx>=out.items.size())continue;Anime e=canon.get(out.items.get(idx).malId);if(e!=null)out.items.set(idx,e);}}
    public Anime yoruShell(Anime base){Anime a=Anime.from(base==null?new JSONObject():base.json());String originalSource=base==null?"":base.source;a.source="yoru";int id=a.malId>0?a.malId:(Sec.s("271b1c121c3e0a111b").equals(originalSource)?parseInt(base.id):0);if(id>0&&a.malId==0)a.malId=id;if(id<=0)id=(int)(1L+Integer.toUnsignedLong((base==null?"yoru":base.key()).hashCode())%999999999L);a.id=String.valueOf(id);a.blocked=false;return a;}
    private Anime yoruDetails(Anime base,boolean episodes)throws Exception{
        Anime a=yoruShell(base);
        Future<Anime> yummyJob=ENRICH.submit(()->{try{return findYummy(base);}catch(Exception e){return null;}});
        Future<Anime> metaJob=null;
        int baseMal=a.malId;
        if(baseMal>0){
            final int mm=baseMal;
            metaJob=ENRICH.submit(()->{try{Anime sh=new Anime();sh.source=Sec.s("271b1c121c3e0a111b");sh.id=String.valueOf(mm);return details(sh,false);}catch(Exception e){return null;}});
        }
        Anime y=null;
        if(!episodes){
            try{y=yummyJob.get(50,TimeUnit.MILLISECONDS);if(y!=null)fillYoruMeta(a,y);}catch(Exception ignored){}
        }else if(yummyJob!=null&&yummyJob.isDone()){
            try{y=yummyJob.get();if(y!=null)fillYoruMeta(a,y);}catch(Exception ignored){}
        }
        if(episodes){
            YoruCache db=YoruApp.app()==null?null:YoruApp.app().cache;
            if(db!=null){
                try{
                    Anime cached=db.detail(a,24*60*60*1000L);
                    if(cached!=null&&!cached.episodeList.isEmpty()&&playableEpisodes(cached)>0){
                        a.episodeList.clear();
                        a.episodeList.addAll(cached.episodeList);
                        a.episodes=Math.max(a.episodes,a.episodeList.size());
                        fillYoruMeta(a,cached);
                        return remember(a);
                    }
                }catch(Exception ignored){}
            }
            if(a.episodeList.isEmpty()){
                ArrayList<Anime> found=yoruFoundSources(base,a,yummyJob);
                LinkedHashMap<String,Anime.Episode> map=new LinkedHashMap<>();
                for(Anime source:found)mergeYoruEpisodes(map,source);
                a.episodeList.clear();
                a.episodeList.addAll(map.values());
                a.episodeList.sort(Comparator.comparingDouble(e->e.number));
                a.episodes=Math.max(a.episodes,a.episodeList.size());
                appendFutureEpisodes(a);
                applyEpisodeVisuals(a);
                if(db!=null&&!a.episodeList.isEmpty())db.detail(a);
                if(a.episodeList.isEmpty()||playableEpisodes(a)<=0){
                    silentSweep(a,base);
                    if(db!=null&&!a.episodeList.isEmpty())db.detail(a);
                }
            }
        }
        Anime meta=null;
        if(metaJob!=null&&metaJob.isDone()){
            try{meta=metaJob.get();}catch(Exception ignored){}
        }else if(metaJob!=null&&!episodes){
            try{meta=metaJob.get(2000,TimeUnit.MILLISECONDS);}catch(Exception ignored){}
        }else if(!episodes){
            try{int mal=y==null?0:y.malId;if(mal>0){Anime sh=new Anime();sh.source=Sec.s("271b1c121c3e0a111b");sh.id=String.valueOf(mal);meta=details(sh,false);}}catch(Exception ignored){}
        }
        try{if(meta!=null){fillYoruMeta(a,meta);for(Anime r:meta.related)a.related.add(r);}}catch(Exception ignored){}
        return remember(a);
    }

    private void fillYoruMeta(Anime target,Anime source){if(target==null||source==null)return;if(target.title.isEmpty())target.title=source.title;if(target.original.isEmpty())target.original=source.original;if(target.alias.isEmpty())target.alias=source.alias;if(target.poster.isEmpty())target.poster=source.poster;if(target.description.isEmpty())target.description=source.description;if(target.year==0)target.year=source.year;if(target.type.isEmpty()||target.type.equals("Аниме"))target.type=source.type;if(target.status.isEmpty())target.status=source.status;if(target.age.isEmpty())target.age=source.age;if(target.studio.isEmpty())target.studio=source.studio;if(target.episodes==0)target.episodes=source.episodes;if(target.episodesAired==0)target.episodesAired=source.episodesAired;if(target.nextEpisodeAt.isEmpty())target.nextEpisodeAt=source.nextEpisodeAt;if(target.malId==0)target.malId=source.malId;if(target.anilistId==0)target.anilistId=source.anilistId;if(target.kpId==0)target.kpId=source.kpId;if(target.libriaAlias.isEmpty())target.libriaAlias=source.libriaAlias;if(target.score==0)target.score=source.score;if(target.trailerUrl.isEmpty())target.trailerUrl=source.trailerUrl;if(target.airedDate.isEmpty())target.airedDate=source.airedDate;for(String shot:source.screenshots)if(!shot.isEmpty()&&!target.screenshots.contains(shot)&&target.screenshots.size()<12)target.screenshots.add(shot);for(String g:source.genres)if(!target.genres.contains(g))target.genres.add(g);}
    private ArrayList<Anime> yoruFoundSources(Anime original,Anime shell,Future<Anime> yummyJob){
        ArrayList<Anime> out=new ArrayList<>();LinkedHashSet<String> seen=new LinkedHashSet<>();
        ArrayList<String> sources=SourceEngine.discoveryOrder(original,shell);String pref="";boolean concrete=false;
        try{pref=YoruApp.app().store.voicePreference();concrete=!voiceKey(pref).isEmpty();}catch(Exception ignored){}
        if(concrete){ArrayList<String> focused=new ArrayList<>();for(String s:sources)if(sourceLikelyHasVoice(s,pref))focused.add(s);for(String s:sources)if(!focused.contains(s))focused.add(s);sources=focused;}
        boolean isMobile=false;
        try{YoruApp app=YoruApp.app();if(app!=null&&app.traffic!=null)isMobile=app.traffic.mobile()||app.traffic.metered();}catch(Exception ignored){}
        String kodikKey=Sec.s("3f1c11101e");
        if(sources.contains(kodikKey)){
            try{
                Anime k=yoruFindSource(original,shell,kodikKey);
                if(k!=null&&!k.episodeList.isEmpty()&&playableEpisodes(k)>0){
                    out.add(k);
                    seen.add(k.source+":"+k.id);
                }
            }catch(Exception ignored){}
        }
        if(isMobile&&sources.size()>4){sources=new ArrayList<>(sources.subList(0,4));}
        ExecutorService pool=Executors.newFixedThreadPool(Math.max(2,Math.min(sources.size()+(isMobile?1:2),isMobile?4:12)));
        CompletionService<Anime> done=new ExecutorCompletionService<>(pool);int jobs=0;
        if(!isMobile&&(!concrete||sourceLikelyHasVoice(Sec.s("2d0618140c"),pref))){done.submit(()->{try{Anime yy=yummyJob==null?null:yummyJob.get(20,TimeUnit.SECONDS);if(yy==null)return null;Anime full=details(yy,true);if(full==null||full.blocked||full.episodeList.isEmpty())return null;return full;}catch(Exception e){return null;}});jobs++;}
        for(String source:sources){if(kodikKey.equals(source)&&!out.isEmpty())continue;done.submit(()->yoruFindSource(original,shell,source));jobs++;}
        boolean firstFound=!out.isEmpty();
        long deadline=System.currentTimeMillis()+(firstFound?(isMobile?350:600):(isMobile?3500:(concrete?8000:10000)));
        try{for(int i=0;i<jobs;i++){long left=deadline-System.currentTimeMillis();if(left<=0)break;Future<Anime> f;try{f=done.poll(left,TimeUnit.MILLISECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();break;}if(f==null)break;try{Anime a=f.get();if(a!=null&&!a.episodeList.isEmpty()&&seen.add(a.source+":"+a.id)){out.add(a);if(!firstFound){firstFound=true;deadline=Math.min(deadline,System.currentTimeMillis()+(isMobile?250:500));}if(enoughYoruSources(out,pref,concrete,shell,isMobile))break;}}catch(Exception ignored){}}}finally{pool.shutdownNow();}
        out.sort(Comparator.comparingInt(a->1000-SourceEngine.score(a.source,a)));return out;
    }
    private boolean enoughYoruSources(ArrayList<Anime> rows,String pref,boolean concrete,Anime shell,boolean isMobile){if(rows==null||rows.isEmpty())return false;int episodes=0;for(Anime a:rows){episodes=Math.max(episodes,a==null?0:a.episodeList.size());}int target=shell==null?0:Math.max(shell.episodes,shell.episodesAired);int needEpisodes=target<=0?1:Math.min(target,6);return episodes>=needEpisodes;}
    private boolean hasPreferredVoice(Anime a,String pref){if(a==null||voiceKey(pref).isEmpty())return false;if(voiceMatches(pref,sourceVoice(a.source)))return true;for(Anime.Episode e:a.episodeList)for(Anime.Variant v:e.variants){String label=(v==null?"":v.name+" "+v.displayName+" "+v.player);if(voiceMatches(pref,label))return true;}return false;}
    private boolean sourceLikelyHasVoice(String source,String voice){String key=voiceKey(voice),s=SourceEngine.sourceId(source);if(key.isEmpty())return true;if(key.equals(Sec.s("351d1c1d0031")))return s.equals(Sec.s("351d1c1d0031"))||s.equals(Sec.s("2d0618140c"))||s.equals(Sec.s("351d1c0106360e021b"))||s.equals(Sec.s("3f1c11101e"));if(key.equals(Sec.s("351d1c1410250a1006")))return s.equals(Sec.s("351d1c1410250a1006"))||s.equals(Sec.s("2d0618140c"))||s.equals(Sec.s("3f1c11101e"));if(key.equals(Sec.s("351d1c1410370c02")))return s.equals(Sec.s("351d1c1410370c02"))||s.equals(Sec.s("2d0618140c"))||s.equals(Sec.s("3f1c11101e"));if(key.equals(Sec.s("351d1c151c31170a13")))return s.equals(Sec.s("351d1c151c31170a13"))||s.equals(Sec.s("351d1c14103f0c01"))||s.equals(Sec.s("351d1c14103f0c01460e"))||s.equals(Sec.s("2d0618140c"));return s.equals(Sec.s("2d0618140c"))||s.equals(Sec.s("351d1c0106360e021b"))||s.equals(Sec.s("3f1c11101e"))||s.equals(Sec.s("351d1c1410270e02"));}
    private void silentSweep(Anime a,Anime base){if(a==null||playableEpisodes(a)>0)return;long deadline=System.currentTimeMillis()+12000;ArrayList<String> order=null;try{order=SourceEngine.playbackOrder(base==null?a:base);}catch(Exception e){return;}if(order==null)return;for(String source:order){if(source==null||source.equals("yoru")||System.currentTimeMillis()>=deadline)continue;Anime got=null;try{got=findPlayableSource(a,source);}catch(Exception ignored){}if(got==null||got.episodeList.isEmpty()||playableEpisodes(got)<=0)continue;LinkedHashMap<String,Anime.Episode> map=new LinkedHashMap<>();try{mergeYoruEpisodes(map,got);}catch(Exception ignored){}if(map.isEmpty())continue;a.episodeList.clear();a.episodeList.addAll(map.values());a.episodeList.sort(Comparator.comparingDouble(e->e.number));a.episodes=Math.max(a.episodes,a.episodeList.size());try{a.episodesAired=Math.max(a.episodesAired,playableEpisodes(a));}catch(Exception ignored){}try{appendFutureEpisodes(a);}catch(Exception ignored){}try{applyEpisodeVisuals(a);}catch(Exception ignored){}try{remember(a);}catch(Exception ignored){}YoruCache db=YoruApp.app()==null?null:YoruApp.app().cache;if(db!=null)try{db.detail(a);}catch(Exception ignored){}break;}}
    private Anime yoruFindSource(Anime original,Anime shell,String source){long started=System.currentTimeMillis();try{Anime candidate;if(source.equals(Sec.s("3f1c11101e")))candidate=kodikShell(shell);else if(source.equals(Sec.s("351d1c0106360e021b")))candidate=findAnix(shell);else if(source.equals(Sec.s("351d1c151c31170a13")))candidate=findAniLiberty(shell);else if(source.equals(Sec.s("3c121b101836")))candidate=findHanime(shell);else if(source.equals(Sec.s("351d1c1410270e02"))||source.equals(Sec.s("351d1c1d0031"))||source.equals(Sec.s("351d1c1410250a1006"))||source.equals(Sec.s("351d1c1410370c02")))candidate=searchSource(shell,source);else candidate=searchSource(shell,source);if(candidate==null&&original!=null&&!original.source.equals("yoru")&&original.source.equals(source))candidate=original;if(candidate==null){SourceEngine.record(source,false,System.currentTimeMillis()-started,0,0,0);return null;}Anime full=(!candidate.episodeList.isEmpty()&&playableEpisodes(candidate)>0)?candidate:details(candidate,true);if(full.blocked||full.episodeList.isEmpty()){SourceEngine.record(source,false,System.currentTimeMillis()-started,0,0,0);return null;}SourceEngine.record(source,true,System.currentTimeMillis()-started,full.episodeList.size(),SourceEngine.optionCount(full),SourceEngine.maxQuality(full));return full;}catch(Exception e){SourceEngine.record(source,false,System.currentTimeMillis()-started,0,0,0);return null;}}
    private void mergeYoruEpisodes(LinkedHashMap<String,Anime.Episode> map,Anime source){String route=downloadSourceName(source.source);for(Anime.Episode e:source.episodeList){if(e==null||e.number<0||!Double.isFinite(e.number))continue;ArrayList<Anime.Variant> variants=new ArrayList<>();String baseVoice=sourceVoice(source.source);for(Map.Entry<Integer,String> stream:e.streams.entrySet()){String url=safeUrl(stream.getValue());if(url.isEmpty())continue;Anime.Variant v=new Anime.Variant(baseVoice,route,url);v.duration=e.duration;v.openingStart=e.openingStart;v.openingEnd=e.openingEnd;v.displayName=baseVoice;variants.add(v);}for(Anime.Variant row:e.variants){String url=embed(row.url);if(url.isEmpty())continue;String rowLabel=cleanLabel(row.name.isEmpty()?row.label():row.name),rowPlayer=cleanLabel(row.player);String voice=voiceTitle(rowLabel);if(voice.isEmpty())voice=sourceVoice(source.source);Anime.Variant v=new Anime.Variant(voice,rowPlayer.isEmpty()?route:route+" · "+rowPlayer,url);v.duration=row.duration;v.openingStart=row.openingStart;v.openingEnd=row.openingEnd;v.displayName=voice;variants.add(v);}if(variants.isEmpty())continue;String key=episodeParam(e.number);Anime.Episode ep=map.get(key);if(ep==null){ep=new Anime.Episode();ep.id="yoru-"+key;ep.number=e.number;ep.name="";ep.lazy="yoru";map.put(key,ep);}if(ep.poster.isEmpty()&&e.poster!=null&&!e.poster.isEmpty())ep.poster=e.poster;ep.duration=Math.max(ep.duration,e.duration);if(ep.openingEnd<=0&&e.openingEnd>0){ep.openingStart=e.openingStart;ep.openingEnd=e.openingEnd;}for(Anime.Variant v:variants)addVariant(ep,v);ep.variants.sort(Comparator.comparingInt(v->SourceEngine.variantRank(v)));}}
    private void loadYoruEpisode(Anime.Episode ep)throws Exception{if("yoru-ready".equals(ep.resolverUrl))return;if(ep.variants.isEmpty()&&!ep.streams.isEmpty()){ep.resolverUrl="yoru-ready";return;}ArrayList<Anime.Variant> sorted=SourceEngine.sortVariants(ep.variants);ArrayList<Anime.Variant> keep=new ArrayList<>();String preferred="";boolean strict=false;try{preferred=YoruApp.app().store.voicePreference();strict=!voiceKey(preferred).isEmpty();}catch(Exception ignored){}collectYoruVariants(sorted,keep,preferred,strict);if(keep.isEmpty()&&strict){collectYoruVariants(sorted,keep,"",false);try{YoruApp.app().store.onlyPreferredVoice(false);}catch(Exception ignored){}}if(keep.isEmpty())throw new IOException("Tsuyu пока не нашёл доступные озвучки для этой серии");ep.variants.clear();for(Anime.Variant v:keep)addVariant(ep,v);ep.variants.sort(Comparator.comparingInt(v->SourceEngine.variantRank(v)));ep.resolverUrl="yoru-ready";}
    private static void collectYoruVariants(ArrayList<Anime.Variant> sorted,ArrayList<Anime.Variant> keep,String preferred,boolean strict){LinkedHashMap<String,Integer> perVoice=new LinkedHashMap<>();for(Anime.Variant v:sorted){String label=v==null?"":v.name+" "+v.displayName+" "+v.player;if(strict&&!voiceMatches(preferred,label))continue;String voice=voiceTitle(v.name.isEmpty()?v.label():v.name);String key=voiceKey(voice);if(key.isEmpty()){voice="Оригинал / Tsuyu Player";key="unknown:"+Integer.toHexString((v.url==null?"":v.url).hashCode());}int count=perVoice.getOrDefault(key,0);if(strict&&count>=3)continue;if(!strict&&count>=2)continue;perVoice.put(key,count+1);Anime.Variant copy=copyVariant(v);if(copy.name.isEmpty()||"Дорожка без названия".equals(copy.name))copy.name=voice;keep.add(copy);if(strict&&keep.size()>=3)break;if(!strict&&(keep.size()>=14||perVoice.size()>=9))break;}}
